;WITH ExpectedRows AS (
    SELECT CheckName,Item,Fields FROM OPENJSON(@ExpectedJson)
    WITH(CheckName nvarchar(100) '$.check',Item nvarchar(1000) '$.item',Fields nvarchar(max) '$.fields' AS JSON)
), Nodes AS (
    SELECT mw.*,c.CompanyName,parent.Description AS ParentName,parent.CompanyID AS ParentCompanyID,
           parent.ParentID AS GrandparentID,tz.Description AS TimeZone
    FROM dbo.MetaWorld_TBL mw JOIN dbo.Company_TBL c ON c.CompanyID=mw.CompanyID
    LEFT JOIN dbo.MetaWorld_TBL parent ON parent.MetaWorldID=mw.ParentID
    LEFT JOIN dbo.TimeZone tz ON tz.TimeZoneID=COALESCE(mw.TimeZoneID,parent.TimeZoneID,c.TimeZoneID)
    WHERE mw.CompanyID>0 AND ISNULL(mw.DeleteInd,0)=0
), Places AS (
    SELECT * FROM Nodes n WHERE n.InternalLevelNbr IN(1,2)
      AND NOT(n.CompanyName=N'Northlake University' AND n.ParentName=N'Weather Reference'
              AND n.Description IN(N'Sacramento Executive Airport',N'Sacramento International Airport'))
), Accounts AS (
    SELECT ba.*,c.CompanyName,p.Name AS ProviderName,
           CONCAT(c.CompanyName,N' | ',p.Name,N' | ',ba.BA_BillingAccountNumber) AS IdentityKey
    FROM dbo.BillingAccount_Tbl ba JOIN dbo.Company_TBL c ON c.CompanyID=ba.CompanyID
    LEFT JOIN dbo.UtilityProvider p ON p.ProviderID=ba.ProviderID WHERE ba.CompanyID>0 AND ISNULL(ba.DeleteInd,0)=0
), AddressEntities AS (
    SELECT N'01 Service addresses' AS CheckName,a.IdentityKey AS Item,a.AD_AddressID_Service AS AD_AddressID FROM Accounts a
    UNION ALL SELECT N'01 Account addresses',a.IdentityKey,a.AD_AddressID_AcctRep FROM Accounts a
    UNION ALL SELECT N'01 Account remit',a.IdentityKey,a.AD_AddressID_Remit FROM Accounts a
    UNION ALL SELECT N'02 Node addresses',CONCAT(n.CompanyName,N' | ',n.Description),n.AD_AddressID FROM Places n
), Points AS (
    SELECT p.*,n.CompanyName,n.Description AS NodeDescription,n.InternalLevelNbr,n.MetaType,n.IndexType,n.BaselineInd,
           n.PtID AS NodePtID,n.CompanyID AS NodeCompanyID,n.ParentID,n.ParentName,n.ParentCompanyID,
           m.SM_Code AS MeterNumber,CONCAT(n.CompanyName,N' | ',m.SM_Code,N' | ',p.Description) AS IdentityKey,
           tz.Description AS TimeZone,pt.Description AS ReadingType,mt.MT_MeasureName AS MeasureType,
           CASE WHEN u.UN_UnitID IS NULL THEN NULL ELSE CONCAT(u.UN_Name,N' - (',u.UN_Units,N')') END AS Unit
    FROM dbo.PointDef_TBL p JOIN Nodes n ON n.MetaWorldID=p.MetaWorldID
    LEFT JOIN dbo.Meter m ON m.MetaWorldID=n.ParentID LEFT JOIN dbo.TimeZone tz ON tz.TimeZoneID=p.TimeZoneID
    LEFT JOIN dbo.PointTypes pt ON pt.PtType=p.PtType LEFT JOIN dbo.MeasureType mt ON mt.MT_MeasureTypeID=p.MT_MeasureTypeID
    LEFT JOIN dbo.Unit u ON u.UN_UnitID=p.UN_UnitID WHERE p.CompanyID>0
), AggregatePoints AS (
    SELECT p.* FROM Points p WHERE EXISTS(SELECT 1 FROM ExpectedRows e WHERE e.CheckName=N'06 Aggregates' AND e.Item=CONCAT(p.CompanyName,N' | ',p.Description))
       OR EXISTS(SELECT 1 FROM dbo.PointAggregatePoints m WHERE m.AggregatePtID=p.PtID)
       OR EXISTS(SELECT 1 FROM dbo.ObjectRegistry o WHERE o.hSiERtdb=p.PtGatewayID AND o.Descriptor=N'Aggregation Gateway')
), ActualRows AS (
    SELECT CONVERT(nvarchar(100),N'01 Billing accounts') AS CheckName,CONVERT(nvarchar(1000),a.IdentityKey) AS Item,
        (SELECT a.BA_Description AS Description,a.BA_PrevBillingAccNumber AS PreviousAccountNumber,u.UN_Name AS CurrencyUnit,
            CASE ISNULL(a.Type_Code,0) WHEN 0 THEN N'No AP Upload' WHEN 1 THEN N'AP Upload Only' WHEN 2 THEN N'Bill Payment' ELSE CONVERT(nvarchar(20),a.Type_Code) END AS BillServiceType,  -- DBAdmin saves No AP Upload as NULL and reads it back as 0
            CASE a.BillType_Code WHEN 0 THEN N'Bill Entry' WHEN 1 THEN N'Bill Importer' WHEN 2 THEN N'Bill Generation' WHEN 3 THEN N'Bill Allocation' WHEN 10 THEN N'Other' ELSE CONVERT(nvarchar(20),a.BillType_Code) END AS BillEntryType,
            t.BillInvoiceTemplateDescription AS BillInvoiceTemplate,a.Status_Code AS Status FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS Fields
    FROM Accounts a LEFT JOIN dbo.Unit u ON u.UN_UnitID=a.BA_CurrUnitID LEFT JOIN dbo.BillInvoiceTemplate t ON t.BillInvoiceTemplateID=a.BillInvoiceTemplateID
    UNION ALL
    SELECT e.CheckName,e.Item,(SELECT a.AD_Address1 AS Address,a.AD_Address2 AS Address2,a.AD_City AS City,RTRIM(a.RE_RegionCode) AS Region,a.AD_PostalCode AS PostalCode,
        co.CO_CountryName AS Country,a.Latitude,a.Longitude FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM AddressEntities e LEFT JOIN dbo.Address a ON a.AD_AddressID=e.AD_AddressID LEFT JOIN dbo.Country co ON co.CO_CountryCode=a.CO_CountryCode
    UNION ALL
    SELECT N'01 Account contacts',a.IdentityKey,(SELECT c.CT_FirstName AS FirstName,c.CT_LastName AS LastName,c.CT_Title AS Title,c.CT_Phone AS Phone,c.CT_Cell AS Cell,c.CT_Email AS Email FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Accounts a LEFT JOIN dbo.Contact c ON c.CT_ContactID=a.CT_ContactID_AcctRep
    UNION ALL
    SELECT N'01 Account status',a.IdentityKey,
        (SELECT (SELECT CONVERT(varchar(10),MIN(h.AsOfDate),120) FROM dbo.StatusHistory h
                 WHERE h.Table_Code=N'BA' AND h.SH_TableRowID=a.BA_BillingAccountID AND h.Status_Code=1) AS FirstActive,
                (SELECT TOP (1) s.Status_Code_Description FROM dbo.StatusHistory h
                 JOIN dbo.Global_Status_Code s ON s.Table_Code=N'BA' AND s.Status_Code=h.Status_Code
                 WHERE h.Table_Code=N'BA' AND h.SH_TableRowID=a.BA_BillingAccountID ORDER BY h.AsOfDate DESC,h.SH_ActionID DESC) AS CurrentStatus
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Accounts a
    UNION ALL
    SELECT N'01 Account notes',CONCAT(a.IdentityKey,N' | ',n.Note),(SELECT CONVERT(bit,1) AS Present FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Accounts a JOIN dbo.NoteHistory n ON n.Table_Code=N'BA' AND n.NT_TableRowID=a.BA_BillingAccountID
    UNION ALL
    SELECT N'02 Sites and buildings',CONCAT(n.CompanyName,N' | ',n.Description),
        (SELECT n.ParentName AS Parent,n.InternalLevelNbr AS Level,n.MetaType AS LevelLabel,n.TimeZone,n.UDFData AS Code,
            CONVERT(bit,CASE WHEN n.ParentID IS NULL OR n.ParentCompanyID=n.CompanyID THEN 1 ELSE 0 END) AS SameCompanyAsParent
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n
    UNION ALL
    SELECT N'02 Department keywords',CONCAT(n.CompanyName,N' | ',n.Description),
        (SELECT kv.Description AS Department FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n JOIN dbo.KeyWordMap_tbl km ON km.MetaWorldId=n.MetaWorldID
    JOIN dbo.KeywordValue_tbl kv ON kv.KeywordValueId=km.KeywordValueId JOIN dbo.KeywordType_tbl kt ON kt.KeywordTypeId=kv.KeywordTypeId
    WHERE kt.Description=N'Department' -- A site's own assignment, and the materialized row each building inherits from it.
    UNION ALL
    SELECT N'02 Node keywords',CONCAT(n.CompanyName,N' | ',n.Description,N' | ',kt.Description),
        (SELECT kv.Description AS Value FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n JOIN dbo.KeyWordMap_tbl km ON km.MetaWorldId=n.MetaWorldID AND km.ParentKeywordMapId IS NULL
    JOIN dbo.KeywordValue_tbl kv ON kv.KeywordValueId=km.KeywordValueId JOIN dbo.KeywordType_tbl kt ON kt.KeywordTypeId=kv.KeywordTypeId
    WHERE kt.Description<>N'Department' -- Direct assignments only; Department has its own section above.
    UNION ALL
    SELECT N'02 Floor areas',CONCAT(n.CompanyName,N' | ',n.Description,N' | ',CONVERT(varchar(10),h.AsOfDate,120)),
        (SELECT h.Value AS Area,u.UN_Units AS Unit FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n JOIN dbo.Value_TBL v ON v.Table_Code=N'M2' AND v.TableRowID=n.MetaWorldID AND v.ValueName=N'Floor Area'
    JOIN dbo.ValueHistory h ON h.ValueID=v.ValueID LEFT JOIN dbo.Unit u ON u.UN_UnitID=v.UN_UnitID
    UNION ALL
    -- Sites have no Status page; every building has its own status rows.
    SELECT N'02 Building status',CONCAT(n.CompanyName,N' | ',n.Description,N' | ',CONVERT(varchar(10),h.AsOfDate,120)),
        (SELECT s.Status_Code_Description AS Status FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n JOIN dbo.StatusHistory h ON h.Table_Code=N'M2' AND h.SH_TableRowID=n.MetaWorldID
    LEFT JOIN dbo.Global_Status_Code s ON s.Table_Code=N'M2' AND s.Status_Code=h.Status_Code
    UNION ALL
    SELECT N'02 Node notes',CONCAT(n.CompanyName,N' | ',n.Description,N' | ',h.Note),(SELECT CONVERT(bit,1) AS Present FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n JOIN dbo.NoteHistory h ON h.Table_Code=N'M2' AND h.NT_TableRowID=n.MetaWorldID
    UNION ALL
    SELECT N'03 Meters',CONCAT(n.CompanyName,N' | ',m.SM_Code),
        (SELECT CASE WHEN n.CompanyName=N'Northlake University' AND ((m.SM_Code=N'KSAC' AND n.ParentName=N'Sacramento Executive Airport')
                        OR (m.SM_Code=N'KSMF' AND n.ParentName=N'Sacramento International Airport'))
                        AND grandparent.Description=N'Weather Reference' AND grandparent.CompanyID=n.CompanyID
                     THEN grandparent.Description ELSE n.ParentName END AS Parent,
            CONVERT(bit,CASE WHEN n.ParentCompanyID=n.CompanyID THEN 1 ELSE 0 END) AS SameCompanyAsParent,
            n.InternalLevelNbr AS Level,n.MetaType AS LevelLabel,n.TimeZone,ba.BA_BillingAccountNumber AS AccountNumber,
            accountCompany.CompanyName AS AccountCompany,n.Description,mt.MT_MeasureName AS MeasureType,m.SM_SerialNumber AS ProviderMeterNumber,
            ISNULL(m.SM_Multiplier,1) AS MeterMultiplier,up.Name AS UtilityProvider,NULLIF(m.BillCycle,0) AS BillCycle,
            (SELECT s.Status_Code_Description FROM dbo.Global_Status_Code s WHERE s.Table_Code=N'SM' AND s.Status_Code=m.Status_Code) AS Status
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Meter m JOIN Nodes n ON n.MetaWorldID=m.MetaWorldID LEFT JOIN dbo.MetaWorld_TBL grandparent ON grandparent.MetaWorldID=n.GrandparentID
    LEFT JOIN dbo.BillingAccount_Tbl ba ON ba.BA_BillingAccountID=m.BA_BillingAccountID LEFT JOIN dbo.Company_TBL accountCompany ON accountCompany.CompanyID=ba.CompanyID
    LEFT JOIN dbo.UtilityProvider up ON up.ProviderID=ba.ProviderID LEFT JOIN dbo.MeasureType mt ON mt.MT_MeasureTypeID=m.MT_MeasureTypeID
    UNION ALL
    SELECT N'03 Meter keywords',CONCAT(n.CompanyName,N' | ',m.SM_Code,N' | ',kt.Description),
        (SELECT kv.Description AS Value,CONVERT(bit,CASE WHEN km.ParentKeywordMapId IS NULL THEN 0 ELSE 1 END) AS Inherited
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Meter m JOIN Nodes n ON n.MetaWorldID=m.MetaWorldID JOIN dbo.KeyWordMap_tbl km ON km.MetaWorldId=m.MetaWorldID
    JOIN dbo.KeywordValue_tbl kv ON kv.KeywordValueId=km.KeywordValueId JOIN dbo.KeywordType_tbl kt ON kt.KeywordTypeId=kv.KeywordTypeId
    WHERE kt.Description<>N'Department' -- Department reaches every meter by inheritance and is checked on the buildings.
    UNION ALL
    SELECT N'03 Meter status',CONCAT(n.CompanyName,N' | ',m.SM_Code,N' | ',CONVERT(varchar(10),h.AsOfDate,120)),
        (SELECT s.Status_Code_Description AS Status FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Meter m JOIN Nodes n ON n.MetaWorldID=m.MetaWorldID
    JOIN dbo.StatusHistory h ON h.Table_Code=N'SM' AND h.SH_TableRowID=m.MetaWorldID
    LEFT JOIN dbo.Global_Status_Code s ON s.Table_Code=N'SM' AND s.Status_Code=h.Status_Code
    -- The node Status page writes a meter's status as SM, the history bill validation reads; only meters the YAML gives
    -- a status are compared (every other meter keeps the Open row Meter_Save wrote on the day it was first saved).
    WHERE EXISTS(SELECT 1 FROM ExpectedRows e WHERE e.CheckName=N'03 Meter status' AND e.Item LIKE CONCAT(n.CompanyName,N' | ',m.SM_Code,N' | %'))
    UNION ALL
    SELECT N'03 Meter notes',CONCAT(n.CompanyName,N' | ',m.SM_Code,N' | ',h.Note),(SELECT CONVERT(bit,1) AS Present FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Meter m JOIN Nodes n ON n.MetaWorldID=m.MetaWorldID JOIN dbo.NoteHistory h ON h.Table_Code=N'M2' AND h.NT_TableRowID=m.MetaWorldID
    UNION ALL
    SELECT N'03 Meter integrity',N'All meters',
        (SELECT (SELECT COUNT(*) FROM dbo.Meter m LEFT JOIN dbo.MetaWorld_TBL n ON n.MetaWorldID=m.MetaWorldID
                    WHERE n.MetaWorldID IS NULL OR (n.CompanyID>0 AND ISNULL(n.DeleteInd,0)<>0)) AS BrokenMeterLinks,
                (SELECT COUNT(*) FROM Nodes n WHERE n.InternalLevelNbr=4 AND NOT EXISTS(SELECT 1 FROM dbo.Meter m WHERE m.MetaWorldID=n.MetaWorldID)) AS NodesWithoutMeter
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    UNION ALL
    SELECT N'04 Points',p.IdentityKey,(SELECT p.ReadingType,p.MeasureType,p.Unit,NULLIF(p.Interval,0) AS ArchiveInterval,
            CASE WHEN p.IndexType=0 THEN N'Degree Days' ELSE i.Description END AS [Index],p.InternalLevelNbr AS Level,p.MetaType AS LevelLabel,p.TimeZone,
            CONVERT(bit,CASE WHEN p.NodePtID=p.PtID AND p.NodeCompanyID=p.CompanyID AND p.ParentCompanyID=p.CompanyID AND p.NodeDescription=p.Description THEN 1 ELSE 0 END) AS NodeLinkValid
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Points p LEFT JOIN dbo.IndexType i ON i.IndexType=p.IndexType
    WHERE p.PtType NOT IN(4,5) AND NOT EXISTS(SELECT 1 FROM dbo.PtRelatedData_TBL r WHERE r.RelatedPtID=p.PtID AND r.ReasonType IN(N'D',N'H',N'C'))
      AND NOT EXISTS(SELECT 1 FROM AggregatePoints a WHERE a.PtID=p.PtID)
    UNION ALL
    SELECT N'04 Generated children',CONCAT(p.IdentityKey,N' | ',kind.Reason),
        (SELECT (SELECT COUNT(*) FROM dbo.PtRelatedData_TBL r WHERE r.PtID=p.PtID AND r.ReasonType=kind.Reason) AS Count,
            (SELECT COUNT(*) FROM dbo.PtRelatedData_TBL r JOIN Points child ON child.PtID=r.RelatedPtID
             WHERE r.PtID=p.PtID AND r.ReasonType=kind.Reason AND child.CompanyID=p.CompanyID AND child.TimeZoneID=p.TimeZoneID
               AND child.NodePtID=child.PtID AND child.NodeCompanyID=child.CompanyID
               AND ((kind.Reason=N'D' AND child.PtType=4 AND child.MT_MeasureTypeID=p.MT_MeasureTypeID AND ISNULL(child.Interval,0)=ISNULL(p.Interval,0))
                 OR (kind.Reason IN(N'H',N'C') AND child.PtType=1 AND child.Interval=1440 AND child.IndexType=CASE kind.Reason WHEN N'H' THEN 1 ELSE 2 END))) AS ValidCount,
            (SELECT TOP (1) child.Unit FROM dbo.PtRelatedData_TBL r JOIN Points child ON child.PtID=r.RelatedPtID
             WHERE r.PtID=p.PtID AND r.ReasonType=kind.Reason ORDER BY child.PtID) AS Unit
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Points p CROSS APPLY(VALUES(N'D'),(N'H'),(N'C')) kind(Reason)
    WHERE (kind.Reason=N'D' AND p.PtType=3) OR (kind.Reason IN(N'H',N'C') AND p.IndexType=0)
    UNION ALL
    SELECT N'04 Point integrity',N'All points',
        (SELECT (SELECT COUNT(*) FROM Points child WHERE (child.PtType=4 OR child.IndexType IN(1,2)) AND NOT EXISTS(
                    SELECT 1 FROM dbo.PtRelatedData_TBL r JOIN Points parent ON parent.PtID=r.PtID WHERE r.RelatedPtID=child.PtID
                    AND ((child.PtType=4 AND r.ReasonType=N'D' AND parent.PtType=3) OR (child.IndexType IN(1,2) AND r.ReasonType=CASE child.IndexType WHEN 1 THEN N'H' ELSE N'C' END AND parent.IndexType=0)))) AS OrphanChildren,
            (SELECT COUNT(*) FROM dbo.PointDef_TBL p LEFT JOIN dbo.MetaWorld_TBL n ON n.MetaWorldID=p.MetaWorldID
             WHERE p.CompanyID>0 AND (n.MetaWorldID IS NULL OR ISNULL(n.DeleteInd,0)<>0 OR ISNULL(n.PtID,0)<>p.PtID OR n.CompanyID<>p.CompanyID)) AS BrokenNodeLinks,
            (SELECT COUNT(*) FROM Nodes n WHERE n.InternalLevelNbr=5 AND NOT EXISTS(SELECT 1 FROM dbo.PointDef_TBL p WHERE p.MetaWorldID=n.MetaWorldID AND p.PtID=n.PtID)) AS NodesWithoutPoint,
            (SELECT COUNT(*) FROM Points p WHERE p.PtType=5) AS UnexpectedROC
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    UNION ALL
    SELECT N'05 Weather stations',CONCAT(n.CompanyName,N' | ',n.Description),
        (SELECT assigned.CompanyName AS AssignmentCompany,station.CompanyName AS StationCompany,m.SM_Code AS StationMeterNumber FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM Places n JOIN dbo.WeatherStationMap_tbl w ON w.MetaWorldId=n.MetaWorldID
    LEFT JOIN dbo.Company_TBL assigned ON assigned.CompanyID=w.CompanyId
    LEFT JOIN Nodes station ON station.MetaWorldID=w.WeatherStationID LEFT JOIN dbo.Meter m ON m.MetaWorldID=w.WeatherStationID
    WHERE n.InternalLevelNbr=2
    UNION ALL
    SELECT N'06 Aggregates',CONCAT(p.CompanyName,N' | ',p.Description),
        (SELECT p.ParentName AS Parent,p.MeasureType,p.Unit,p.Interval,p.ReadingType,p.TimeZone,p.InternalLevelNbr AS Level,p.MetaType AS LevelLabel,o.Descriptor AS Gateway
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM AggregatePoints p LEFT JOIN dbo.ObjectRegistry o ON o.hSiERtdb=p.PtGatewayID
    UNION ALL
    SELECT N'06 Aggregate members',CONCAT(a.CompanyName,N' | ',a.Description,N' | ',p.IdentityKey),
        (SELECT m.Required,m.Multiplier FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.PointAggregatePoints m JOIN AggregatePoints a ON a.PtID=m.AggregatePtID LEFT JOIN Points p ON p.PtID=m.PtID
    -- Baselines are checked in Stage 3 (stage-3-gateways-and-data/checks.sql), after the measured points have gateways.
    UNION ALL
    SELECT N'00 Units',u.UN_Name,
        (SELECT u.UN_Units AS Label,c.UT_UnitClassName AS UnitClass,numerator.UN_Name AS NumeratorUnit,denominator.UN_Name AS DenominatorUnit
         FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.Unit u LEFT JOIN dbo.UnitClass c ON c.UT_UnitClassID=u.UT_UnitClassID
    LEFT JOIN dbo.Unit numerator ON numerator.UN_UnitID=NULLIF(u.UN_NumerUnitID,0) LEFT JOIN dbo.Unit denominator ON denominator.UN_UnitID=NULLIF(u.UN_DenomUnitID,0)
    WHERE EXISTS(SELECT 1 FROM ExpectedRows e WHERE e.CheckName=N'00 Units' AND e.Item=u.UN_Name)
    UNION ALL
    SELECT N'00 Unit measure types',CONCAT(u.UN_Name,N' | ',mt.MT_MeasureName),
        (SELECT CONVERT(bit,x.UN_CommodityInd) AS IsCommodity FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.MeasureTypeUnit x JOIN dbo.Unit u ON u.UN_UnitID=x.UN_UnitID JOIN dbo.MeasureType mt ON mt.MT_MeasureTypeID=x.MT_MeasureTypeID
    WHERE EXISTS(SELECT 1 FROM ExpectedRows e WHERE e.CheckName=N'00 Unit measure types' AND e.Item=CONCAT(u.UN_Name,N' | ',mt.MT_MeasureName))
       -- A unit Northlake adds has exactly the recipe's measure types; a seeded unit may keep others it shipped with.
       OR EXISTS(SELECT 1 FROM ExpectedRows e WHERE e.CheckName=N'00 Units' AND e.Item=u.UN_Name)
    UNION ALL
    SELECT N'00 Unit conversions',CONCAT(u.UN_Name,N' | ',f.UN_Name),
        (SELECT x.UC_Mult_Coef AS Multiply,x.UC_Add_Coef AS Offset FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
    FROM dbo.UnitConversion x JOIN dbo.Unit u ON u.UN_UnitID=x.UN_UnitID JOIN dbo.Unit f ON f.UN_UnitID=x.UC_ConversionFromID
    WHERE EXISTS(SELECT 1 FROM ExpectedRows e WHERE e.CheckName=N'00 Unit conversions' AND e.Item=CONCAT(u.UN_Name,N' | ',f.UN_Name))
), AdditionalIssues AS (
    -- An aggregate is registered once it has members (the API's SaveAggregate refuses one without), so only an
    -- aggregate with members is expected to have the row. Database Administrator never writes it (product finding 14).
    SELECT CONVERT(nvarchar(100),N'06 Aggregates') AS CheckName,CONCAT(p.CompanyName,N' | ',p.Description) AS Item,
        CONVERT(nvarchar(128),N'Calculation registration') AS Field,CONVERT(nvarchar(max),N'PointAggregates_TBL row once it has members') AS Expected,
        CONVERT(nvarchar(max),N'Missing after its members were saved (product finding 14)') AS Actual,N'WARN' AS Severity
    FROM AggregatePoints p WHERE EXISTS(SELECT 1 FROM dbo.PointAggregatePoints m WHERE m.AggregatePtID=p.PtID)
      AND NOT EXISTS(SELECT 1 FROM dbo.PointAggregates_TBL a WHERE a.AggregatePtID=p.PtID)
)
SELECT @ExpectedSnapshot=(SELECT CheckName,Item,JSON_QUERY(Fields) AS Fields FROM ExpectedRows FOR JSON PATH),
       @ActualSnapshot=(SELECT CheckName,Item,JSON_QUERY(Fields) AS Fields FROM ActualRows FOR JSON PATH),
       @AdditionalSnapshot=(SELECT * FROM AdditionalIssues FOR JSON PATH);
-- Capture rows once so repeated summaries do not repeat database or JSON work.
SELECT * INTO #StageCheckExpected FROM OPENJSON(@ExpectedSnapshot)
WITH(CheckName nvarchar(100),Item nvarchar(1000),Fields nvarchar(max) AS JSON);
SELECT * INTO #StageCheckActual FROM OPENJSON(@ActualSnapshot)
WITH(CheckName nvarchar(100),Item nvarchar(1000),Fields nvarchar(max) AS JSON);
SELECT * INTO #StageCheckAdditional FROM OPENJSON(@AdditionalSnapshot)
WITH(CheckName nvarchar(100),Item nvarchar(1000),Field nvarchar(128),Expected nvarchar(max),Actual nvarchar(max),Severity nvarchar(4));
;WITH ExpectedRows AS (SELECT * FROM #StageCheckExpected),
ActualRows AS (SELECT * FROM #StageCheckActual),
AdditionalIssues AS (SELECT * FROM #StageCheckAdditional), ExpectedCounts AS (
    SELECT CheckName, Item, COUNT(*) AS RecordCount FROM ExpectedRows GROUP BY CheckName, Item
), ActualCounts AS (
    SELECT CheckName, Item, COUNT(*) AS RecordCount FROM ActualRows GROUP BY CheckName, Item
), Counts AS (
    SELECT COALESCE(e.CheckName,a.CheckName) AS CheckName, COALESCE(e.Item,a.Item) AS Item,
           ISNULL(e.RecordCount,0) AS ExpectedCount, ISNULL(a.RecordCount,0) AS ActualCount
    FROM ExpectedCounts e FULL JOIN ActualCounts a ON a.CheckName=e.CheckName AND a.Item=e.Item
), Issues AS (
    SELECT CheckName,Item,CONVERT(nvarchar(128),N'Presence / uniqueness') AS Field,
           CONVERT(nvarchar(max),ExpectedCount) AS Expected,CONVERT(nvarchar(max),ActualCount) AS Actual,N'FAIL' AS Severity
    FROM Counts WHERE ExpectedCount<>ActualCount OR ExpectedCount>1 OR ActualCount>1
    UNION ALL
    SELECT e.CheckName,e.Item,ef.[key] COLLATE DATABASE_DEFAULT,COALESCE(ef.value,N'(blank)'),COALESCE(af.value,N'(blank)'),N'FAIL'
    FROM ExpectedRows e JOIN ActualRows a ON a.CheckName=e.CheckName AND a.Item=e.Item
    JOIN Counts c ON c.CheckName=e.CheckName AND c.Item=e.Item AND c.ExpectedCount=1 AND c.ActualCount=1
    CROSS APPLY OPENJSON(e.Fields) ef
    OUTER APPLY (SELECT [key],value,[type] FROM OPENJSON(a.Fields) WHERE [key]=ef.[key]) af
    WHERE af.[key] IS NULL OR CASE WHEN (
        (ef.[type]=2 AND af.[type]=2
            AND COALESCE(TRY_CONVERT(decimal(38,6),ef.value),TRY_CONVERT(decimal(38,6),TRY_CONVERT(float,ef.value)))
                =COALESCE(TRY_CONVERT(decimal(38,6),af.value),TRY_CONVERT(decimal(38,6),TRY_CONVERT(float,af.value))))
        OR (ef.[key]=N'Phone' AND REPLACE(TRANSLATE(ef.value,N'()+-.',N'     '),N' ',N'')=REPLACE(TRANSLATE(af.value,N'()+-.',N'     '),N' ',N''))
        OR (NOT(ef.[type]=2 AND af.[type]=2) AND
            ISNULL(NULLIF(LTRIM(RTRIM(ef.value)),N''),N'<NULL>')=ISNULL(NULLIF(LTRIM(RTRIM(af.value)),N''),N'<NULL>'))) THEN 1 ELSE 0 END=0
    UNION ALL
    SELECT CheckName,Item,Field,Expected,Actual,Severity FROM AdditionalIssues
)
SELECT * INTO #StageCheckIssues FROM Issues;
;WITH ExpectedRows AS (SELECT * FROM #StageCheckExpected),
ActualRows AS (SELECT * FROM #StageCheckActual),
AdditionalIssues AS (SELECT * FROM #StageCheckAdditional),
Issues AS (SELECT * FROM #StageCheckIssues),
Sections AS (
    SELECT CheckName FROM ExpectedRows UNION SELECT CheckName FROM ActualRows UNION SELECT CheckName FROM AdditionalIssues
), Summary AS (
    SELECT s.CheckName,
        (SELECT COUNT(*) FROM ExpectedRows e WHERE e.CheckName=s.CheckName) AS ExpectedRows,
        (SELECT COUNT(*) FROM ActualRows a WHERE a.CheckName=s.CheckName) AS ActualRows,
        (SELECT COUNT(*) FROM Issues i WHERE i.CheckName=s.CheckName AND Severity=N'FAIL') AS Failures,
        (SELECT COUNT(*) FROM Issues i WHERE i.CheckName=s.CheckName AND Severity=N'WARN') AS Warnings
    FROM Sections s
), OutputRows AS (
    SELECT 0 AS SortOrder,CONVERT(nvarchar(100),CONCAT(N'ALL STAGE ',@Stage)) AS [Check],
        CASE WHEN EXISTS(SELECT 1 FROM Issues WHERE Severity=N'FAIL') THEN N'FAIL'
             WHEN EXISTS(SELECT 1 FROM Issues WHERE Severity=N'WARN') THEN N'WARN' ELSE N'PASS' END AS [Status],
        CONVERT(nvarchar(1000),N'Overall stored-configuration result') AS Item,CONVERT(nvarchar(128),N'Expected / actual records') AS Field,
        CONVERT(nvarchar(max),(SELECT COUNT(*) FROM ExpectedRows)) AS Expected,
        CONVERT(nvarchar(max),(SELECT COUNT(*) FROM ActualRows)) AS Actual,
        (SELECT COUNT(*) FROM Issues WHERE Severity=N'FAIL') AS Failures,
        (SELECT COUNT(*) FROM Issues WHERE Severity=N'WARN') AS Warnings
    UNION ALL
    SELECT 1,CheckName,CASE WHEN Failures>0 THEN N'FAIL' WHEN Warnings>0 THEN N'WARN' ELSE N'PASS' END,
        N'Section summary',N'Expected / actual records',CONVERT(nvarchar(max),ExpectedRows),CONVERT(nvarchar(max),ActualRows),Failures,Warnings
    FROM Summary
    UNION ALL
    SELECT 2,CheckName,Severity,Item,Field,Expected,Actual,CASE WHEN Severity=N'FAIL' THEN 1 ELSE 0 END,CASE WHEN Severity=N'WARN' THEN 1 ELSE 0 END
    FROM Issues WHERE @ShowDetails=1
)
SELECT [Check],[Status],Item,Field,Expected,Actual,Failures,Warnings
FROM OutputRows ORDER BY SortOrder,[Check],Item,Field;
DROP TABLE IF EXISTS #StageCheckExpected,#StageCheckActual,#StageCheckAdditional,#StageCheckIssues;
